def min_lexicographical_string(n, k, s):
    count = [0] * 2
    for char in s:
        count[int(char)] += 1

    left_zeros = 0
    right_ones = count[1]

    for i in range(n):
        if s[i] == '0':
            left_zeros += 1
        else:
            right_ones -= 1

        if left_zeros + right_ones <= k:
            return '0' * left_zeros + '1' * (n - left_zeros)

    return s

