def min_binary_string(n, k, s):
    ones = s.count('1')
    if ones == 0 or ones >= n - k:
        return ''.join(sorted(s))

    result = list(s)
    i = 0
    while i < n - 1 and k > 0:
        if result[i] == '1':
            j = i + 1
            while j < n and result[j] == '1':
                j += 1
            if j < n:
                result[i], result[j] = result[j], result[i]
                k -= (j - i)
        i += 1

    return ''.join(result)

