def min_string(s, k):
    s = list(s)
    i = 0
    while i < len(s) - 1 and k > 0:
        if s[i] == '1':
            j = i + 1
            while j < len(s) and s[j] == '1' and k >= j - i:
                j += 1
            if j < len(s):
                s[i], s[j] = s[j], s[i]
                k -= j - i
        i += 1
    return ''.join(s)

