def min_lexicographical_string(n, k, s):
    zeros = [i for i, char in enumerate(s) if char == '0']
    ones = [i for i, char in enumerate(s) if char == '1']

    result = list(s)
    zero_index = 0
    one_index = 0

    for i in range(n):
        if zero_index < len(zeros) and (one_index >= len(ones) or zeros[zero_index] <= ones[one_index]):
            if i - zeros[zero_index] <= k:
                result[i], result[zeros[zero_index]] = result[zeros[zero_index]], result[i]
                k -= (i - zeros[zero_index])
                zero_index += 1
            else:
                break
        elif one_index < len(ones):
            if i - ones[one_index] <= k:
                result[i], result[ones[one_index]] = result[ones[one_index]], result[i]
                k -= (i - ones[one_index])
                one_index += 1
            else:
                break

    return ''.join(result)

